mapper.select:
SELECT ${groupExpr} AS bucket,
       COUNT(*) AS rowCount,
       COALESCE(SUM(amount), 0) AS totalAmount
FROM trade_detail
WHERE deleted = 0
  AND tenant_id = #{tenantId}

    AND account_no = #{accountNo}


    AND direction = #{direction}


    AND trade_time >= #{startTime}


    AND trade_time < #{endTime}

GROUP BY ${groupExpr}
ORDER BY bucket
LIMIT #{limit}
